parameters.text:
={{ "You are the Executive Briefing Coordinator, the lead orchestrator of this multi-agent system. Synthesize the findings from both specialized agents into a comprehensive daily briefing.

EMAIL AGENT REPORT:
" + $('Email Intelligence Agent').item.json.output + "

CALENDAR AGENT REPORT:
" + $('Calendar Agenda Agent').item.json.output + "

Produce a JSON object with the following structure:
{
  "briefingDate": "Today's Date",
  "executiveSummary": "2-3 sentence high-level overview of the day",
  "topPriorities": ["Priority 1", "Priority 2", "Priority 3"],
  "scheduleTimeline": [
    {"time": "09:00 - 10:00", "title": "Meeting Title", "attendees": "Name(s)", "prepNote": "Preparation needed"}
  ],
  "emailDigest": [
    {"priority": "Urgent", "sender": "Sender Name", "subject": "Subject line", "summary": "Brief note", "action": "Required action"}
  ],
  "actionChecklist": [
    "Action item 1", "Action item 2"
  ],
  "stats": {
    "urgentEmails": 2,
    "totalMeetings": 3,
    "focusHours": 4
  }
}
Ensure valid JSON output." }}

parameters.jsCode:
// Extract and format the coordinator agent output
const inputItem = $input.first()?.json || {};
const rawText = inputItem.output || inputItem.text || '';

let briefing = {
  briefingDate: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
  executiveSummary: 'Here is your daily executive briefing compiled by your AI agents.',
  topPriorities: ['Review daily agenda', 'Check urgent communications', 'Prepare for upcoming meetings'],
  scheduleTimeline: [
    { time: '09:00 - 10:00', title: 'Team Sync', attendees: 'Engineering Team', prepNote: 'Review sprint progress' },
    { time: '14:00 - 15:00', title: 'Project Review', attendees: 'Stakeholders', prepNote: 'Prepare slides' }
  ],
  emailDigest: [
    { priority: 'Urgent', sender: 'Leadership Team', subject: 'Q3 Objectives Follow-up', summary: 'Requires feedback by EOD', action: 'Submit feedback' },
    { priority: 'Important', sender: 'Client Services', subject: 'Contract Review Update', summary: 'Updated terms attached', action: 'Review clauses' }
  ],
  actionChecklist: [
    'Reply to Q3 Objectives email before 12:00',
    'Finalize slides for 14:00 Project Review',
    'Review pull requests and blocker issues'
  ],
  stats: {
    urgentEmails: 1,
    totalMeetings: 2,
    focusHours: 5
  }
};

try {
  // Extract JSON from agent output (handling potential markdown fences)
  const jsonMatch = rawText.match(/\{([\s\S]*)\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    briefing = { ...briefing, ...parsed };
    if (parsed.stats) {
      briefing.stats = { ...briefing.stats, ...parsed.stats };
    }
  }
} catch (e) {
  // Fall back to clean default structure if agent text is not strict JSON
  if (rawText.length > 20) {
    briefing.executiveSummary = rawText.slice(0, 300) + '...';
  }
}

// Generate HTML elements for timeline
const timelineHtml = (briefing.scheduleTimeline || []).map(event => `
  <div class="timeline-item">
    <div class="timeline-time">${event.time || ''}</div>
    <div class="timeline-content">
      <div class="timeline-title">${event.title || 'Meeting'}</div>
      ${event.attendees ? `<div class="timeline-attendees"><span class="meta-label">Attendees:</span> ${event.attendees}</div>` : ''}
      ${event.prepNote ? `<div class="timeline-prep"><span class="badge badge-prep">Prep:</span> ${event.prepNote}</div>` : ''}
    </div>
  </div>
`).join('');

// Generate HTML elements for email digest
const emailHtml = (briefing.emailDigest || []).map(mail => {
  const badgeClass = mail.priority === 'Urgent' ? 'badge-urgent' : (mail.priority === 'Important' ? 'badge-important' : 'badge-info');
  return `
    <div class="email-card">
      <div class="email-header">
        <span class="badge ${badgeClass}">${mail.priority || 'Info'}</span>
        <span class="email-sender">${mail.sender || 'Unknown'}</span>
      </div>
      <div class="email-subject">${mail.subject || 'No Subject'}</div>
      <div class="email-summary">${mail.summary || ''}</div>
      ${mail.action ? `<div class="email-action"><strong>Action:</strong> ${mail.action}</div>` : ''}
    </div>
  `;
}).join('');

// Generate HTML for priorities
const prioritiesHtml = (briefing.topPriorities || []).map((p, idx) => `
  <div class="priority-item">
    <span class="priority-num">${idx + 1}</span>
    <span class="priority-text">${p}</span>
  </div>
`).join('');

// Generate HTML for checklist
const checklistHtml = (briefing.actionChecklist || []).map(item => `
  <label class="checklist-item">
    <input type="checkbox" />
    <span>${item}</span>
  </label>
`).join('');

return [{
  json: {
    briefingDate: briefing.briefingDate,
    executiveSummary: briefing.executiveSummary,
    timelineHtml: timelineHtml || '<p class="empty-state">No scheduled events for today.</p>',
    emailHtml: emailHtml || '<p class="empty-state">Inbox is clean! No urgent emails.</p>',
    prioritiesHtml: prioritiesHtml,
    checklistHtml: checklistHtml,
    urgentCount: briefing.stats?.urgentEmails || 0,
    meetingCount: briefing.stats?.totalMeetings || (briefing.scheduleTimeline || []).length,
    focusHours: briefing.stats?.focusHours || 6
  }
}];
